import java.util.*;
public class Main {
  public static void main(String[] args) {
    double[] a={1,12,5,7,3};int k=2;double best=-1e100;for(int i=0;i+k<=a.length;i++){double s=0;for(int j=i;j<i+k;j++)s+=a[j];best=Math.max(best,s/k);}System.out.printf("%.6f%n",best);
  }
}

